import { sprintf }				from 'sprintf-js';
import { AccCatId, type AccConfig, type AccService, type SrvCharacteristic, type GeneratorContext, type GeneratorResult } from '../types';
import { constChar, onlyAck } from '../helpers';


// ~~~~~~~~~
// FRITZ_MAP
// ~~~~~~~~~
// accessory generated by create_fritzdect() for a productname; 'Name' is added last
//		TargetHeatingCoolingState:	0 := OFF, 1 := HEAT, 2 := COOL, 3 := AUTO
//		CurrentHeatingCoolingState:	0 := OFF, 1 := HEAT, 2 := COOL
const FRITZ_MAP: Record<string, { category: string, type: string, chars: (id: string) => SrvCharacteristic[], historyIds: string[] }> = {
	'FRITZ!DECT Repeater 100': {
		category: AccCatId.Sensor, type: 'TemperatureSensor',
		chars: id => [ onlyAck('CurrentTemperature', `${id}.celsius`) ],
		historyIds: [ 'celsius' ],
	},
	'FRITZ!Smart Energy 200': {
		category: AccCatId.Switch, type: 'Switch',
		chars: id => [ onlyAck('On', `${id}.state`) ],
		historyIds: [ 'state' ],
	},
	'FRITZ!Smart Thermo 301': {
		category: AccCatId.Thermostat, type: 'Thermostat',
		chars: id => [
			constChar('TemperatureDisplayUnits',	0),
			onlyAck  ('TargetTemperature',			`${id}.tsoll`),
			onlyAck  ('CurrentTemperature',			`${id}.tist`),
			constChar('TargetHeatingCoolingState',	3),
			onlyAck  ('CurrentHeatingCoolingState',	`${id}.heatingCoolingState`),
		],
		historyIds: [ 'tsoll', 'tist' ],
	},
};


export async function createFritzdect({ adapter, srcInstId }: GeneratorContext): Promise<GeneratorResult> {
	const accConfigs: AccConfig[] = [];
	const historyIds: string[] = [];

	// fritzdect channels
	const channels = await adapter.getForeignObjectsAsync(`${srcInstId}.*`, 'channel');
	for (const channel of Object.values(channels)) {
		const productname = await adapter.getForeignStateAsync(`${channel._id}.productname`);
		if (productname) {
			const product = Object.hasOwn(FRITZ_MAP, String(productname.val)) ? FRITZ_MAP[String(productname.val)] : undefined;
			if (! product) {
				adapter.log.error(sprintf('%-30s %-20s %-50s %s', 'create_fritzdect()', 'unknown', 'productname', String(productname.val)));
			} else {
				const characteristics = product.chars(channel._id);
				for (const historyId of product.historyIds) {
					historyIds.push(`${channel._id}.${historyId}`);
				}

				const idPath	= channel._id.split('.');						// [ 'fritzdect', '0', '0.DECT_099950049519' ]
				const grpName	= idPath.slice(0, 2).join('.');
				const nameObj	= await adapter.getForeignStateAsync(`${channel._id}.name`);
				const devName	= (typeof nameObj?.val === 'string') ? nameObj.val : 'unknown';

				// add Name characteristic
				characteristics.push(constChar('Name', devName));

				// accConfig
				const manufacturer	= await adapter.getForeignStateAsync(`${channel._id}.manufacturer`);
				const fwVersion		= await adapter.getForeignStateAsync(`${channel._id}.fwversion`);
				const accConfig: AccConfig = {
					'category':			product.category,
					'groupString':		grpName,								// used by adapter only
					'name':				channel._id,							// NOTE: yahka adapter uses 'name' to build homekit UUID!
					'manufacturer':		String(manufacturer?.val ?? 'n/a'),		// visible within iOS home app
					'model':			devName,								// visible within iOS home app
					'firmware':			String(fwVersion   ?.val ?? 'n/a'),		// visible within iOS home app
					'serial':			idPath[2] ?? '',						// visible within iOS home app
					'services':			[],
				};
				accConfigs.push(accConfig);

				// accService
				const accService: AccService = {
					'type': product.type, 'subType': '', 'name': devName, 'characteristics': characteristics
				};
				accConfig.services.push(accService);
				adapter.log.debug(sprintf('%-30s %-20s %-50s %s', 'create_fritzdect()', accService.type, accConfig.name, accService.name));
			}
		}
	}

	return { devices: accConfigs, invalid: [], historyIds };

}
